    'pw.faq.heading': 'Frequently Asked Questions',
    'pw.faq.q1': 'Is this password generator truly secure?',
    'pw.faq.a1': 'Yes. We use the Web Crypto API (crypto.getRandomValues()), which provides cryptographically secure random numbers. This is the same standard used for encryption and security certificates. Unlike Math.random(), it cannot be predicted.',
