    'pw.faq.a4': 'A strong password combines length (12+ characters), randomness (not a dictionary word), and variety (uppercase, lowercase, numbers, and symbols). Our strength meter measures entropy — the mathematical measure of unpredictability — to give you an accurate assessment.',
