    'pw.faq.q6': 'What is entropy and why does it matter?',
    'pw.faq.a6': 'Entropy measures the unpredictability of a password in bits. Higher entropy means more possible combinations an attacker would need to try. A password with 80+ bits of entropy is considered very strong. Our generator shows you the entropy in real time.',

