    'wc.features.everyday.title': 'Everyday Utility',
    'wc.features.everyday.desc': 'Check essay word limits, Twitter/X character counts, Instagram caption length, or blog post reading time. One tool for all your writing needs.',
    'wc.faq.heading': 'FAQ',
    'wc.faq.q1': 'How does the word counter work?',
    'wc.faq.a1': 'The counter splits your text by spaces and punctuation to count words. Characters are counted directly from the text string. Sentences are detected by period, question mark, and exclamation point endings. Paragraphs are separated by line breaks.',
    'wc.faq.q2': 'How is reading time calculated?',
    'wc.faq.a2': 'Reading time is based on the industry standard of 200 words per minute. For example, a 1000-word article takes about 5 minutes to read. This is the same metric used by Medium and other popular blogging platforms.',
    'wc.faq.q3': 'What is keyword density?',
    'wc.faq.a3': 'Keyword density shows how often each word appears relative to the total word count. For example, if "marketing" appears 10 times in a 500-word text, its density is 2%. SEO professionals use this to ensure target keywords appear enough — but not too much.',
    'wc.faq.q4': 'Is my text stored anywhere?',
    'wc.faq.a4': 'No. Your text is processed entirely in your browser using JavaScript. It is never sent to our servers or any third party. When you close the page, the text is gone. This makes our counter safe for unpublished manuscripts and sensitive documents.',
    'wc.faq.q5': 'Does it work for non-English text?',
    'wc.faq.a5': 'Yes! The counter works with any language — English, Spanish, Arabic, Chinese, Russian, and more. Word counting logic adapts to different writing systems. Arabic and Chinese text are counted accurately based on their specific word boundaries.',
    'wc.limits.heading': 'Character Limits',
