    'qr.features.heading': 'Por Qué Este Generador QR Es Diferente',
    'qr.features.noSignup.title': 'Sin Registro Necesario',
    'qr.features.noSignup.desc': 'Comienza a generar códigos QR inmediatamente. Sin cuenta, sin email, sin fricción — simplemente abre y crea.',
    'qr.features.noWatermark.title': 'Sin Marca de Agua',
    'qr.features.noWatermark.desc': 'Tus códigos QR son limpios y profesionales. A diferencia de la competencia, nunca añadimos marcas de agua a los códigos QR gratuitos.',
    'qr.features.noExpiration.title': 'Sin Caducidad',
    'qr.features.noExpiration.desc': 'Los códigos QR estáticos funcionan para siempre. Sin períodos de prueba, sin fechas de caducidad, sin paywalls sorpresa después de 14 días.',
    'qr.features.privacyFirst.title': 'Privacidad Primero',
    'qr.features.privacyFirst.desc': 'Tus datos nunca salen de tu navegador. Sin procesamiento en servidor, sin rastreo, sin recopilación de datos. Solo usamos Cloudflare Web Analytics — sin cookies, sin PII.',
    'qr.faq.heading': 'Preguntas Frecuentes',
    'qr.faq.q1': '¿Este generador de códigos QR es realmente gratuito?',
    'qr.faq.a1': 'Sí, completamente gratuito sin costes ocultos. Sin registro necesario, sin niveles premium, sin anuncios. Cada función — incluyendo exportación SVG y personalización — está disponible sin cargo.',
    'qr.faq.q2': '¿Los códigos QR caducan?',
    'qr.faq.a2': 'No. Este generador crea códigos QR estáticos que funcionan para siempre. Algunos competidores ofrecen códigos QR "dinámicos" que caducan tras un período de prueba y luego te cobran — nosotros no hacemos eso.',
    'qr.faq.q3': '¿Se envían mis datos a algún servidor?',
    'qr.faq.a3': 'No. El código QR se genera completamente en tu navegador usando JavaScript. Tus URLs, contraseñas WiFi, contactos y texto nunca salen de tu dispositivo. No tenemos acceso a tus datos.',
    'qr.faq.q4': '¿Qué tipos de códigos QR puedo crear?',
    'qr.faq.a4': 'Puedes generar códigos QR para URLs (enlaces a sitios web), credenciales WiFi (para que los invitados se conecten con un escaneo), tarjetas de contacto vCard (tarjetas de presentación digitales) y texto plano. Más tipos próximamente.',
    'qr.faq.q5': '¿Puedo personalizar los colores de mi código QR?',
    'qr.faq.a5': '¡Sí! Puedes elegir cualquier color principal y de fondo. Recomendamos mantener un alto contraste para un escaneo fiable. Color principal oscuro sobre fondo claro funciona mejor.',
    'qr.faq.q6': '¿Qué es la corrección de errores y qué nivel debo elegir?',
    'qr.faq.a6': 'La corrección de errores permite que un código QR se lea incluso si está parcialmente dañado. El nivel L recupera 7% de datos, M 15%, Q 25% y H 30%. Niveles más altos crean códigos QR más densos. Para la mayoría de usos, M es el mejor equilibrio. Elige H si planeas añadir un logotipo.',

