    'wl.qr.download': 'Descargar QR',
    'wl.share.label': 'Comparte tu enlace',
    'wl.preview.label': 'Así verán tu enlace tus usuarios',

    'wl.seo.what.heading': '¿Qué Es un Enlace de WhatsApp?',
    'wl.seo.what.text': 'Un enlace de WhatsApp (también llamado enlace click-to-chat) usa el protocolo oficial wa.me para que cualquiera pueda iniciar una conversación con usted en WhatsApp con un solo clic — sin guardar su número primero. Cuando alguien hace clic en su enlace, WhatsApp se abre con un mensaje predefinido listo para enviar. Funciona en cualquier dispositivo, navegador y lugar del mundo. Los negocios ponen estos enlaces en bios de Instagram, sitios web, firmas de correo, folletos impresos e incluso en códigos QR en ubicaciones físicas. OPN Chat genera estos enlaces gratis, completamente en su navegador — nada se almacena en ningún servidor.',
    'wl.seo.why.heading': '¿Por Qué Crear un Enlace de WhatsApp?',
    'wl.seo.why.feature1.title': 'Contacto en Un Clic',
    'wl.seo.why.feature1.desc': 'Sus clientes o contactos pueden comunicarse con usted al instante. Sin guardar números, sin buscar — solo clic y chatear.',
    'wl.seo.why.feature2.title': 'Mensajes Predefinidos',
    'wl.seo.why.feature2.desc': 'Agrega un mensaje predeterminado para que las personas sepas exactamente qué decir al contactarte. Ideal para consultas comerciales y seguimiento de pedidos.',
    'wl.seo.why.feature3.title': 'Código QR Incluido',
    'wl.seo.why.feature3.desc': 'Cada enlace viene con un código QR gratis. Imprímelo en tarjetas de presentación, menús, fachadas — escanea y chatea al instante.',
    'wl.seo.why.feature4.title': 'Funciona en Todo Lugar',
    'wl.seo.why.feature4.desc': 'Pon tu enlace en tu bio de Instagram, Facebook, Twitter, firma de correo, sitio web, catálogo de WhatsApp Business — donde la gente pueda hacer clic.',
    'wl.seo.how.heading': 'Cómo Funciona',
    'wl.seo.how.text': 'Crear un enlace de WhatsApp con OPN Chat toma menos de un minuto. Ingresa tu número de teléfono con código de país, opcionalmente escriba un mensaje predefinido que los usuarios verán al abrir el chat, y haz clic en "Generar". Obtendrás un enlace wa.me como https://wa.me/15551234567?text=Hola que puedes copiar, compartir e incrustar en un código QR. Sin registro, sin almacenamiento en servidor, todo funciona en tu navegador.',
    'wl.seo.use.heading': 'Dónde Usar Tu Enlace de WhatsApp',
    'wl.seo.use.text': 'Los enlaces de WhatsApp son increíblemente versátiles. Ponlos en tu bio de Instagram — es uno de los lugares más comunes. Agrégalo a la página de contacto de tu sitio web para que los visitantes te envíen mensajes directamente. Inclúyelo en firmas de correo para seguimientos rápidos. Imprime códigos QR en tarjetas de presentación, menús de restaurantes, folletos de eventos o empaques de entrega. Incrusta enlaces en anuncios de Facebook para convertir clics en conversaciones. Úsalos en catálogos de WhatsApp Business para consultas de productos. Las posibilidades son infinitas.',
    'wl.seo.faq.heading': 'Preguntas Frecuentes',
    'wl.seo.faq.q1': '¿Es gratis crear un enlace de WhatsApp?',
    'wl.seo.faq.a1': 'Sí, completamente gratis. OPN Chat genera enlaces wa.me sin costo, sin límites, sin registro y sin anuncios. Los enlaces funcionan para siempre — están basados en el protocolo oficial de WhatsApp.',
    'wl.seo.faq.q2': '¿Qué es el mensaje predefinido?',
    'wl.seo.faq.a2': 'El mensaje predefinido es un texto predeterminado que aparece en el campo de chat cuando alguien abre tu enlace. Facilita que las personas inicien una conversación y te ayuda a saber de dónde vinieron. Por ejemplo: "Hola, quiero saber más sobre sus servicios."',
    'wl.seo.faq.q3': '¿La otra persona necesita tener mi número guardado?',
    'wl.seo.faq.a3': 'No. Cuando alguien hace clic en tu enlace wa.me, WhatsApp abre un chat con tu número independientemente de si lo tiene guardado. Sin embargo, si tienes configuraciones de privacidad que restringen mensajes de contactos desconocidos, pueden necesitar agregar tu número primero.',
    'wl.seo.faq.q4': '¿Puedo cambiar el enlace después?',
    'wl.seo.faq.a4': 'La estructura del enlace wa.me es fija (wa.me/CODIGODEPAIS+NÚMERO). Si cambias tu número, necesitas generar un enlace nuevo. El mensaje predefinido se puede cambiar en cualquier momento generando un nuevo enlace con un mensaje diferente.',
    'wl.seo.faq.q5': '¿Funciona en mi país?',
    'wl.seo.faq.a5': 'Sí, los enlaces wa.me funcionan en todos los países donde WhatsApp está disponible oficialmente. OPN Chat simplemente genera el enlace — el chat real ocurre por WhatsApp mismo, usando su protocolo oficial.',

