    'cv.meta.title': 'Conversor de Unidades — Grátis e Instantâneo | OPN Chat',
    'cv.meta.description': 'Converta unidades instantaneamente: comprimento, peso, temperatura, volume, velocidade, área e dados. cm para polegadas, kg para libras, km para milhas, Celsius para Fahrenheit e mais. Grátis, privado, sem cadastro.',
