    'np.features.heading': 'Por que usar o OPN Notepad?',
    'np.features.local.title': '100% Armazenamento Local',
    'np.features.local.desc': 'Suas notas são salvas no localStorage do seu navegador. Sem nuvem, sem servidor, sem conta. Seus dados nunca saem do seu dispositivo.',
    'np.features.instant.title': 'Instantâneo e Rápido',
    'np.features.instant.desc': 'Sem telas de carregamento, sem espera. Abra a página e comece a digitar. O salvamento automático garante que você nunca perca seu trabalho.',
    'np.features.private.title': 'Completamente Privado',
    'np.features.private.desc': 'Sem rastreamento, sem análises, sem coleta de dados. O que você digita fica entre você e seu navegador. Ponto.',
    'np.features.free.title': 'Grátis Para Sempre',
    'np.features.free.desc': 'Sem planos premium, sem anúncios, sem cadastro. Apenas um bloco de notas limpo e simples que funciona em qualquer dispositivo.',

    'np.faq.heading': 'Perguntas Frequentes',
    'np.faq.q1': 'Onde minhas notas são salvas?',
    'np.faq.a1': 'Suas notas são salvas no localStorage do seu navegador. Isso significa que ficam armazenadas apenas no seu dispositivo. Se você limpar os dados do navegador ou usar um navegador diferente, suas notas não estarão disponíveis lá.',
    'np.faq.q2': 'Posso acessar minhas notas de outro dispositivo?',
    'np.faq.a2': 'Não, como as notas são salvas localmente no seu navegador, não é possível acessá-las de outro dispositivo. Isso é um recurso de privacidade — seus dados nunca saem do seu dispositivo. Se precisar transferir notas, use a função Exportar para salvá-las como arquivo de texto.',
    'np.faq.q3': 'Perderei minhas notas se fechar o navegador?',
    'np.faq.a3': 'Não, suas notas são salvas automaticamente no localStorage enquanto você digita. Elas estarão lá quando você voltar. Porém, se você limpar os dados locais do navegador ou usar o modo anônimo, as notas serão perdidas.',
    'np.faq.q4': 'Existe um limite de notas que posso criar?',
    'np.faq.a4': 'localStorage geralmente permite 5-10 MB por site, o que é suficiente para milhares de notas de texto. Se você atingir o limite, pode exportar notas antigas e excluí-las para liberar espaço.',
    'np.faq.q5': 'Posso exportar minhas notas?',
    'np.faq.a5': 'Sim! Clique no botão Exportar para baixar todas as suas notas como arquivo de texto simples. Você também pode copiar notas individuais para a área de transferência.',

