    'pw.features.heading': 'Por Que Usar Nosso Gerador?',
    'pw.features.crypto.title': 'Criptograficamente Seguro',
    'pw.features.crypto.desc': 'Usa crypto.getRandomValues() — o mesmo padrão de aleatoriedade usado em criptografia. Não Math.random().',
    'pw.features.local.title': '100% Processamento Local',
    'pw.features.local.desc': 'Suas senhas são geradas no seu navegador e nunca enviadas a lugar nenhum. Zero participação do servidor.',
    'pw.features.custom.title': 'Totalmente Personalizável',
    'pw.features.custom.desc': 'Controle o comprimento, tipos de caracteres e gere múltiplas senhas de uma vez. Suas regras, suas senhas.',
    'pw.features.free.title': 'Grátis e Sem Cadastro',
    'pw.features.free.desc': 'Sem conta, sem limites, sem anúncios. Apenas abra e gere. Funciona em qualquer dispositivo.',

    'pw.faq.heading': 'Perguntas Frequentes',
    'pw.faq.q1': 'Este gerador de senhas é realmente seguro?',
    'pw.faq.a1': 'Sim. Usamos a API Web Crypto (crypto.getRandomValues()), que fornece números aleatórios criptograficamente seguros. É o mesmo padrão usado para criptografia e certificados de segurança. Diferente de Math.random(), não pode ser previsto.',
    'pw.faq.q2': 'Minhas senhas geradas são armazenadas em algum lugar?',
    'pw.faq.a2': 'Não. Todas as senhas são geradas inteiramente no seu navegador usando JavaScript. Nada é enviado aos nossos servidores ou a qualquer serviço externo. Ao fechar ou atualizar a página, as senhas geradas desaparecem.',
    'pw.faq.q3': 'Quão longa deve ser minha senha?',
    'pw.faq.a3': 'Recomendamos pelo menos 16 caracteres para segurança forte. Para contas de alta segurança (bancos, e-mail), use 20+ caracteres com todos os tipos habilitados. Cada caractere adicional aumenta exponencialmente as combinações possíveis.',
    'pw.faq.q4': 'O que torna uma senha forte?',
    'pw.faq.a4': 'Uma senha forte combina comprimento (12+ caracteres), aleatoriedade (não uma palavra do dicionário) e variedade (maiúsculas, minúsculas, números e símbolos). Nosso medidor de força mede a entropia — a medida matemática de imprevisibilidade — para uma avaliação precisa.',
    'pw.faq.q5': 'Posso gerar múltiplas senhas de uma vez?',
    'pw.faq.a5': 'Sim! Use a seção "Gerar em Lote" para criar até 10 senhas de uma vez. Você pode copiar todas com um clique.',
    'pw.faq.q6': 'O que é entropia e por que importa?',
    'pw.faq.a6': 'Entropia mede a imprevisibilidade de uma senha em bits. Maior entropia significa mais combinações possíveis que um atacante precisaria testar. Uma senha com 80+ bits de entropia é considerada muito forte. Nosso gerador mostra a entropia em tempo real.',

