    'qr.features.heading': 'Por Que Este Gerador QR É Diferente',
    'qr.features.noSignup.title': 'Sem Cadastro Necessário',
    'qr.features.noSignup.desc': 'Comece a gerar códigos QR imediatamente. Sem conta, sem email, sem atrito — basta abrir e criar.',
    'qr.features.noWatermark.title': 'Sem Marca d\'Água',
    'qr.features.noWatermark.desc': 'Seus códigos QR são limpos e profissionais. Ao contrário dos concorrentes, nunca adicionamos marcas d\'água em códigos QR gratuitos.',
    'qr.features.noExpiration.title': 'Sem Expiração',
    'qr.features.noExpiration.desc': 'Códigos QR estáticos funcionam para sempre. Sem períodos de teste, sem datas de expiração, sem paywalls surpresa após 14 dias.',
    'qr.features.privacyFirst.title': 'Privacidade Primeiro',
    'qr.features.privacyFirst.desc': 'Seus dados nunca saem do seu navegador. Sem processamento no servidor, sem rastreamento, sem coleta de dados. Usamos apenas Cloudflare Web Analytics — sem cookies, sem PII.',
    'qr.faq.heading': 'Perguntas Frequentes',
    'qr.faq.q1': 'Este gerador de códigos QR é realmente gratuito?',
    'qr.faq.a1': 'Sim, completamente gratuito sem custos ocultos. Sem cadastro necessário, sem funções premium, sem anúncios. Cada recurso — incluindo exportação SVG e personalização — está disponível gratuitamente.',
    'qr.faq.q2': 'Os códigos QR expiram?',
    'qr.faq.a2': 'Não. Este gerador cria códigos QR estáticos que funcionam para sempre. Alguns concorrentes oferecem códigos QR "dinâmicos" que expiram após um período de teste e depois cobram — nós não fazemos isso.',
    'qr.faq.q3': 'Meus dados são enviados para algum servidor?',
    'qr.faq.a3': 'Não. O código QR é gerado inteiramente no seu navegador usando JavaScript. Suas URLs, senhas WiFi, contatos e texto nunca saem do seu dispositivo. Não temos acesso aos seus dados.',
    'qr.faq.q4': 'Que tipos de códigos QR posso criar?',
    'qr.faq.a4': 'Você pode gerar códigos QR para URLs (links para sites), credenciais WiFi (para convidados se conectarem com um escaneamento), cartões de contato vCard (cartões de visita digitais) e texto simples. Mais tipos em breve.',
    'qr.faq.q5': 'Posso personalizar as cores do meu código QR?',
    'qr.faq.a5': 'Sim! Você pode escolher qualquer cor principal e de fundo. Recomendamos manter alto contraste para um escaneamento confiável. Cor principal escura sobre fundo claro funciona melhor.',
    'qr.faq.q6': 'O que é correção de erros e qual nível devo escolher?',
    'qr.faq.a6': 'A correção de erros permite que um código QR seja lido mesmo se parcialmente danificado. O nível L recupera 7% dos dados, M 15%, Q 25% e H 30%. Níveis mais altos criam códigos QR mais densos. Para a maioria dos usos, M é o melhor equilíbrio. Escolha H se planeja adicionar um logotipo.',

