    'wc.faq.heading': 'Perguntas Frequentes',
    'wc.faq.q1': 'Como funciona o contador de palavras?',
    'wc.faq.a1': 'O contador divide seu texto por espaços e pontuação para contar palavras. Caracteres são contados diretamente. Frases são detectadas por ponto final, interrogação e exclamação. Parágrafos são separados por quebras de linha.',
    'wc.faq.q2': 'Como o tempo de leitura é calculado?',
    'wc.faq.a2': 'O tempo de leitura baseia-se no padrão de 200 palavras por minuto. Por exemplo, um artigo de 1000 palavras leva cerca de 5 minutos. É a mesma métrica usada pelo Medium.',
    'wc.faq.q3': 'O que é densidade de palavras-chave?',
    'wc.faq.a3': 'Densidade mostra quão frequente cada palavra aparece em relação ao total. Se "marketing" aparece 10 vezes em 500 palavras, a densidade é 2%. Profissionais de SEO usam isso para otimizar conteúdo.',
    'wc.faq.q4': 'Meu texto é armazenado em algum lugar?',
