    'wl.meta.title': 'Generator Link WhatsApp — Gratis & Instan | OPN Chat',
    'wl.meta.description': 'Buat link WhatsApp (wa.me) dengan pesan yang sudah diisi. Bagikan link Anda di bio Instagram, website, kartu nama. Gratis, privat, tanpa daftar.',
