    'wl.seo.what.heading': 'Apa Itu Link WhatsApp?',
    'wl.seo.what.text': 'Link WhatsApp (juga disebut link click-to-chat) menggunakan protokol resmi wa.me agar siapa pun bisa memulai percakapan dengan Anda di WhatsApp dalam satu klik — tanpa menyimpan nomor Anda terlebih dahulu. Saat seseorang mengklik link Anda, WhatsApp terbuka dengan pesan yang sudah diisi siap dikirim. Berfungsi di perangkat apa pun, peramban apa pun, dan di mana saja di dunia. Bisnis menempatkan link ini di bio Instagram, website, signature email, flyer cetakan, dan bahkan kode QR di lokasi fisik. OPN Chat menghasilkan link ini gratis, sepenuhnya di browser Anda — tidak ada yang disimpan di server mana pun.',
    'wl.seo.why.heading': 'Mengapa Membuat Link WhatsApp?',
    'wl.seo.why.feature1.title': 'Kontak Satu Klik',
    'wl.seo.why.feature1.desc': 'Pelanggan atau kontak Anda bisa menghubungi Anda langsung. Tanpa simpan nomor, tanpa cari — hanya klik dan mulai chat.',
    'wl.seo.why.feature2.title': 'Pesan yang Sudah Diisi',
    'wl.seo.why.feature2.desc': 'Tambahkan pesan default agar orang tahu persis apa yang harus dikatakan saat menghubungi Anda. Cocok untuk pertanyaan bisnis dan pelacakan pesanan.',
    'wl.seo.why.feature3.title': 'Kode QR Termasuk',
    'wl.seo.why.feature3.desc': 'Setiap link dilengkapi kode QR gratis. Cetak di kartu nama, menu, etalase — scan dan chat instan.',
    'wl.seo.why.feature4.title': 'Berfungsi di Mana Saja',
    'wl.seo.why.feature4.desc': 'Letakkan link Anda di bio Instagram, Facebook, Twitter, signature email, website, katalog WhatsApp Business — di mana pun orang bisa mengklik.',
    'wl.seo.how.heading': 'Cara Kerjanya',
    'wl.seo.how.text': 'Membuat link WhatsApp dengan OPN Chat kurang dari satu menit. Masukkan nomor telepon Anda dengan kode negara, optionally tulis pesan yang sudah diisi yang akan dilihat pengguna saat membuka chat, dan klik "Buat". Anda mendapatkan link wa.me seperti https://wa.me/15551234567?text=Halo yang bisa disalin, dibagikan, dan dimasukkan dalam kode QR. Tanpa daftar, tanpa penyimpanan server, semuanya terjadi di browser Anda.',
    'wl.seo.use.heading': 'Di Mana Menggunakan Link WhatsApp Anda',
    'wl.seo.use.text': 'Link WhatsApp sangat serbaguna. Letakkan di bio Instagram — ini adalah salah satu tempat paling umum. Tambahkan ke halaman kontak website agar pengunjung bisa mengirim pesan langsung. Sertakan di signature email untuk follow-up cepat. Cetak kode QR di kartu nama, menu restoran, flyer acara, atau kemasan pengiriman. Sematkan di iklan Facebook untuk mengonversi klik menjadi percakapan. Gunakan di katalog WhatsApp Business untuk pertanyaan produk. Kemungkinan tak terbatas.',
    'wl.seo.faq.heading': 'Pertanyaan yang Sering Diajukan',
    'wl.seo.faq.q1': 'Apakah gratis membuat link WhatsApp?',
    'wl.seo.faq.a1': 'Ya, sepenuhnya gratis. OPN Chat menghasilkan link wa.me tanpa biaya, tanpa batas, tanpa daftar, dan tanpa iklan. Link berfungsi selamanya — berdasarkan protokol resmi WhatsApp.',
    'wl.seo.faq.q2': 'Apa itu pesan yang sudah diisi?',
    'wl.seo.faq.a2': 'Pesan yang sudah diisi adalah teks default yang muncul di bidang chat saat seseorang membuka link Anda. Memudahkan orang untuk memulai percakapan dan membantu Anda tahu dari mana mereka datang. Misalnya: "Halo, saya ingin tahu lebih lanjut tentang layanan Anda."',
    'wl.seo.faq.q3': 'Apakah orang lain harus menyimpan nomor saya?',
    'wl.seo.faq.a3': 'Tidak. Saat seseorang mengklik link wa.me Anda, WhatsApp membuka chat dengan nomor Anda tanpa memandang apakah mereka sudah menyimpannya. Namun, jika Anda memiliki pengaturan privasi yang membatasi pesan dari kontak yang tidak dikenal, mereka mungkin perlu menambahkan nomor Anda terlebih dahulu.',
    'wl.seo.faq.q4': 'Bisakah saya mengubah link nanti?',
    'wl.seo.faq.a4': 'Struktur link wa.me bersifat tetap (wa.me/KODENEGARA+NOMOR). Jika Anda mengubah nomor, Anda perlu membuat link baru. Pesan yang sudah diisi bisa diubah kapan saja dengan membuat link baru dengan pesan yang berbeda.',
    'wl.seo.faq.q5': 'Apakah berfungsi di negara saya?',
    'wl.seo.faq.a5': 'Ya, link wa.me berfungsi di setiap negara di mana WhatsApp tersedia secara resmi. OPN Chat hanya menghasilkan link — chat aktual terjadi melalui WhatsApp sendiri, menggunakan protokol resmi mereka.',

