    // SEO — WhatsApp
    'seo.opn.heading': 'Что означает OPN?',
    'seo.opn.text': 'OPN — аббревиатура <strong>O</strong>nline <strong>P</strong>rivacy <strong>N</strong>etwork (Онлайн Сеть Приватности). Мы выбрали это имя, потому наш инструмент создан с подходом «приватность прежде всего». Мы никогда не сохраняем, не регистрируем и не отслеживаем номера телефонов или сообщения, которые вы вводите. Всё происходит безопасно внутри вашего браузера, гарантируя полный контроль над вашими данными.',
    'seo.without.heading': 'WhatsApp без сохранения номера',
    'seo.without.text': 'OPN Chat позволяет мгновенно начать разговор в WhatsApp с любым номером телефона — без необходимости сохранять контакт. Нужно связаться с курьером, компанией или продавцом на маркетплейсе? Просто вводите номер и открывайте чат прямо в WhatsApp. Это самый быстрый способ написать кому-то в WhatsApp, не захламляя список контактов.',
    'seo.how.heading': 'Как это работает',
    'seo.how.text': 'Использовать OPN Chat просто — занимает всего несколько секунд. Введите номер телефона с кодом страны и, если хотите, напишите сообщение, которое будет предзаполнено в чате. Нажмите «Открыть чат в WhatsApp» — и вы перейдёте прямо к разговору. Без регистрации, без установки приложений, без данных на серверах — всё работает прямо в вашем браузере.',
    'seo.why.heading': 'Почему стоит использовать OPN Chat?',
    'seo.why.feature1.title': 'Мгновенный доступ',
    'seo.why.feature1.desc': 'Откройте чат WhatsApp за секунды. Без сохранения контактов, без скачивания приложений, без создания аккаунтов.',
    'seo.why.feature2.title': '100% приватно',
    'seo.why.feature2.desc': 'Мы не храним данные на наших серверах. Ваши номера телефонов и сообщения остаются только в вашем браузере.',
    'seo.why.feature3.title': 'Работает везде',
    'seo.why.feature3.desc': 'Работает с любым номером телефона в мире. Используйте на любом устройстве — телефон, планшет или компьютер. Без установки.',
    'seo.why.feature4.title': 'Предзаполненные сообщения',
    'seo.why.feature4.desc': 'Напишите сообщение перед открытием чата. Идеально для деловых запросов, быстрых знакомств или напоминаний.',
    'seo.cases.heading': 'Частые ситуации использования',
    'seo.cases.text': 'OPN Chat полезен в десятках повседневных ситуаций. Свяжитесь с курьером или доставкой, не добавляя их в контакты. Напишите продавцу на Авито, OLX или Яндекс.Маркет. Обратитесь в компанию или к поставщику услуг без сохранения номера. Отправьте быстрое сообщение человеку, которого вы только встретили на мероприятии. Свяжитесь с арендодателями, водителями такси или персоналом отеля во время путешествий — всё без засорения списка контактов.',
    'seo.direct.heading': 'Прямое сообщение в WhatsApp — умный способ',
    'seo.direct.text': 'Также известный как «WhatsApp Direct» или «Click to Chat», OPN Chat использует официальный протокол ссылок wa.me для открытия чата с любым номером. Это значит, ваше сообщение отправляется через собственную безопасную инфраструктуру WhatsApp. OPN Chat просто предоставляет удобный интерфейс — мы никогда не перехватываем, не читаем и не храним ваши сообщения. Это то же самое, что вручную вводить ссылку wa.me, только быстрее и проще.',
    'seo.faq.heading': 'Часто задаваемые вопросы',
    'seo.faq.q1': 'Нужно ли что-то устанавливать?',
    'seo.faq.a1': 'Нет. OPN Chat работает в любом браузере на любом устройстве. Вам只需要 установить WhatsApp на телефон или компьютер для получения чата.',
    'seo.faq.q2': 'Видит ли другой человек мой номер телефона?',
    'seo.faq.a2': 'Да — если вы отправите сообщение, получатель увидит ваш номер WhatsApp как в обычном разговоре. OPN Chat просто открывает чат, он не делает ваш номер анонимным.',
    'seo.faq.q3': 'Нужно ли другому человеку сохранить мой номер?',
    'seo.faq.a3': 'Нет. Ваше сообщение будет доставлено в любом случае. Однако, если у человека настроены строгие параметры приватности, ограничивающие сообщения от неизвестных контактов, ему может понадобиться добавить ваш номер.',
    'seo.faq.q4': 'OPN Chat бесплатный?',
    'seo.faq.a4': 'Да, OPN Chat полностью бесплатен. Без скрытых платежей, без премиум-уровней, без рекламы. Мы верим, что общение должно быть доступным для всех.',
    'seo.faq.q5': 'Что происходит с номерами, которые вы вводите?',
    'seo.faq.a5': 'Ничего не отправляется на наши серверы. Ваши последние номера сохраняются локально в localStorage вашего браузера только для удобства. Вы можете удалить их в любой момент, очистив данные браузера.',
